import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import API from './api/axiosClient';
import Login from './pages/Login';
import Register from './pages/Register';
import CustomerDashboard from './pages/CustomerDashboard';
import WorkerDashboard from './pages/WorkerDashboard';
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';

const queryClient = new QueryClient();

export default function App() {
    const orgId = 'org_alpha'; 
    const machineId = 'MACH_01';
    const [userRole, setUserRole] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        API.get(`/auth/${orgId}/me`)
            .then(res => setUserRole(res.data.role))
            .catch(() => setUserRole(null))
            .finally(() => setLoading(false));
    }, [orgId]);

    if (loading) return <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center">Loading...</div>;

    return (
        <QueryClientProvider client={queryClient}>
            <Router>
                {userRole && <Navbar role={userRole} />}
                <Routes>
                    <Route path="/login" element={<Login orgId={orgId} />} />
                    <Route path="/register" element={<Register orgId={orgId} />} />

                    <Route path="/customer" element={
                        <ProtectedRoute allowedRoles={['customer']} userRole={userRole}>
                            <CustomerDashboard orgId={orgId} />
                        </ProtectedRoute>
                    } />

                    <Route path="/worker" element={
                        <ProtectedRoute allowedRoles={['worker', 'admin']} userRole={userRole}>
                            <WorkerDashboard orgId={orgId} machineId={machineId} />
                        </ProtectedRoute>
                    } />

                    <Route path="*" element={<Navigate to="/login" replace />} />
                </Routes>
            </Router>
        </QueryClientProvider>
    );
}
